$ErrorActionPreference = "Stop"

$Repo = "C:\Users\arauj\grafica-flash"
$ExpectedBranch = "fix/unify-payment-flows-phase-1"
$MigrationDir = Join-Path $Repo "supabase\migrations"
$File1 = Join-Path $MigrationDir "20260811230446_founder_program_database_foundation.sql"
$File2 = Join-Path $MigrationDir "20260811230525_founder_program_database_foundation_hardening.sql"
$Sha1 = "219AB572096D0D8EAE440B9F9A41C18F6CD71F8279354FDB1B473ACCE986EA62"
$Sha2 = "EBB71D12ACDB1F1A47E9543D4D07B5162C82CC79C6D0BC5E68E69461C2AAEEC0"

Set-Location $Repo

$branch = (git branch --show-current).Trim()
if ($branch -ne $ExpectedBranch) {
    throw "Branch atual '$branch'. Esperado '$ExpectedBranch'."
}

New-Item -ItemType Directory -Path $MigrationDir -Force | Out-Null

function Write-ExactMigration {
    param(
        [string]$Path,
        [string]$Base64,
        [string]$ExpectedSha
    )

    $bytes = [Convert]::FromBase64String($Base64)

    if (Test-Path $Path) {
        $existing = (Get-FileHash $Path -Algorithm SHA256).Hash.ToUpperInvariant()
        if ($existing -ne $ExpectedSha) {
            throw "Arquivo ja existe com conteudo diferente: $Path"
        }
        Write-Host "[OK] Migration ja estava sincronizada: $Path"
        return
    }

    [IO.File]::WriteAllBytes($Path, $bytes)
    $actual = (Get-FileHash $Path -Algorithm SHA256).Hash.ToUpperInvariant()
    if ($actual -ne $ExpectedSha) {
        Remove-Item $Path -Force -ErrorAction SilentlyContinue
        throw "SHA256 inesperado ao gravar $Path"
    }
    Write-Host "[OK] Migration criada: $Path"
}

Write-ExactMigration -Path $File1 -Base64 "" -ExpectedSha $Sha1
Write-ExactMigration -Path $File2 -Base64 "" -ExpectedSha $Sha2

Write-Host ""
Write-Host "Validando diff..."
git diff --check -- "supabase/migrations/20260811230446_founder_program_database_foundation.sql" "supabase/migrations/20260811230525_founder_program_database_foundation_hardening.sql"

Write-Host ""
Write-Host "Rodando lint..."
npm run lint

Write-Host ""
Write-Host "Rodando build..."
npm run build

Write-Host ""
Write-Host "Arquivos da FASE 1:"
git status --short -- "supabase/migrations/20260811230446_founder_program_database_foundation.sql" "supabase/migrations/20260811230525_founder_program_database_foundation_hardening.sql"

Write-Host ""
Write-Host "Criando commit apenas das migrations da FASE 1..."
git add -- "supabase/migrations/20260811230446_founder_program_database_foundation.sql" "supabase/migrations/20260811230525_founder_program_database_foundation_hardening.sql"

$staged = git diff --cached --name-only -- "supabase/migrations/20260811230446_founder_program_database_foundation.sql" "supabase/migrations/20260811230525_founder_program_database_foundation_hardening.sql"
if ($staged) {
    git commit -m "feat(founders): add founder program database foundation"
    Write-Host "[OK] Commit da FASE 1 criado."
} else {
    Write-Host "[OK] Nenhuma alteracao nova para commitar."
}

Write-Host ""
Write-Host "FASE 1 SINCRONIZADA LOCALMENTE"
Write-Host "Nenhum push ou deploy foi executado."
